package dev.pedro.learning.ecommerce.payment.provider;
import jakarta.enterprise.context.ApplicationScoped;import java.util.UUID;import java.util.concurrent.ConcurrentHashMap;import java.util.concurrent.ThreadLocalRandom;import java.util.concurrent.atomic.AtomicInteger;
@ApplicationScoped public class FakePaymentProviderState{private volatile PaymentProviderMode mode=PaymentProviderMode.NORMAL;private volatile int failFirstN=3;private volatile long delayMs=1500;private volatile int failurePercentage=50;private final AtomicInteger calls=new AtomicInteger();private final AtomicInteger successes=new AtomicInteger();private final AtomicInteger failures=new AtomicInteger();private final ConcurrentHashMap<String,ProviderPaymentResponse> successfulByKey=new ConcurrentHashMap<>();
 public ProviderPaymentResponse process(ProviderPaymentRequest request){ProviderPaymentResponse existing=successfulByKey.get(request.idempotencyKey());if(existing!=null)return existing;int call=calls.incrementAndGet();switch(mode){case DECLINE->{failures.incrementAndGet();return ProviderPaymentResponse.failed("Payment declined");}case ALWAYS_FAIL->{return fail("Provider unavailable");}case SLOW->sleep(delayMs);case FAIL_FIRST_N_ATTEMPTS->{if(call<=failFirstN)return fail("Configured failure "+call+"/"+failFirstN);}case FAIL_PERCENTAGE->{if(ThreadLocalRandom.current().nextInt(100)<failurePercentage)return fail("Configured percentage failure");}default->{}}
  successes.incrementAndGet();ProviderPaymentResponse response=new ProviderPaymentResponse(true,"pay_"+UUID.randomUUID(),"approved");successfulByKey.put(request.idempotencyKey(),response);return response;}
 private ProviderPaymentResponse fail(String message){failures.incrementAndGet();throw new jakarta.ws.rs.ServiceUnavailableException(message);}private void sleep(long millis){try{Thread.sleep(millis);}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException("Provider interrupted",e);}}
 public void configureMode(PaymentProviderMode mode){this.mode=mode;}public PaymentProviderMode mode(){return mode;}public void failFirstN(int n){failFirstN=Math.max(0,n);}public int failFirstN(){return failFirstN;}public void delayMs(long ms){delayMs=Math.max(0,ms);}public long delayMs(){return delayMs;}public void failurePercentage(int p){failurePercentage=Math.max(0,Math.min(100,p));}public int failurePercentage(){return failurePercentage;}public int calls(){return calls.get();}public int successes(){return successes.get();}public int failures(){return failures.get();}public void reset(){mode=PaymentProviderMode.NORMAL;failFirstN=3;delayMs=1500;failurePercentage=50;calls.set(0);successes.set(0);failures.set(0);successfulByKey.clear();}
}